# Let me check connectivity of similar values
from collections import deque

def find_connected_components(grid, target_val):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == target_val and (r, c) not in visited:
                comp = []
                queue = deque([(r, c)])
                while queue:
                    cr, cc = queue.popleft()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == target_val and (nr, nc) not in visited:
                            queue.append((nr, nc))
                components.append(comp)
    return components

